def rate(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("Rate must be a finite real non-boolean number")
    if not math.isfinite(value) or value < 0:
        raise ValueError("Rate must be finite and nonnegative")
    return float(value)

def embed(a, region, dims):
    """Actual local matrix algebra embedding, identity on complementary factors."""
    region = tuple(region)
    local_dims = tuple(dims[i] for i in region)
    ld = math.prod(local_dims)
    if a.shape != (ld, ld): raise ValueError("Local operator dimension mismatch")
    n = math.prod(dims)
    tuples = list(itertools.product(*[range(d) for d in dims]))
    out = np.zeros((n,n), complex)
    for i, ii in enumerate(tuples):
        li = int(np.ravel_multi_index(tuple(ii[k] for k in region), local_dims)) if region else 0
        for j, jj in enumerate(tuples):
            if all(ii[k] == jj[k] for k in range(len(dims)) if k not in region):
                lj = int(np.ravel_multi_index(tuple(jj[k] for k in region), local_dims)) if region else 0
                out[i,j] = a[li,lj]
    return out


def liouvillian(h, jumps):
    d = len(h); eye = np.eye(d)
    out = -1j*(np.kron(eye,h)-np.kron(h.T,eye))
    for raw_rate, j in jumps:
        gamma = rate(raw_rate)
        q = j.conj().T@j
        out += gamma*(np.kron(j.conj(),j)-.5*np.kron(eye,q)-.5*np.kron(q.T,eye))
    return out


def direct_generator(h,jumps,rho):
    out = -1j*(h@rho-rho@h)
    for gamma,j in jumps:
        q = j.conj().T@j
        out += gamma*(j@rho@j.conj().T-.5*(q@rho+rho@q))
    return out

def calculate(plan):
    import numpy as np
    import scipy
    from scipy.linalg import expm
    from scipy.integrate import solve_ivp
    helper=next(s['path'] for s in plan['sources'] if s['path'].endswith('finite_device_functions_r62.py'))
    spec=importlib.util.spec_from_file_location('frozen_finite_r64',helper);old=importlib.util.module_from_spec(spec);spec.loader.exec_module(old)
    checks=[]
    def check(name,value,bound=1e-8,greater=False):
        value=float(value);checks.append({'name':name,'value':value,'bound':bound,'relation':'gt' if greater else 'le',
            'passed':bool(math.isfinite(value) and (value>bound if greater else value<=bound))})
    def cj(z):return {'re':float(complex(z).real),'im':float(complex(z).imag)}
    def M(l,theta):
        d=l.shape[0]
        return (np.exp(-1j*theta)*np.kron(np.eye(d),l)+np.exp(1j*theta)*np.kron(l.conj(),np.eye(d)))/math.sqrt(2)
    def filtered(gen,ports,thetas,rho0,filters,label,shot=True):
        d=len(rho0);d2=d*d;n=len(ports);pairs=[(j,k) for j in range(n) for k in range(j,n)]
        maps=[M(l,th) for l,th in zip(ports,thetas)];blocks=1+n+len(pairs)
        y0=np.zeros((blocks,d2),complex);y0[0]=old.vec(rho0)
        for j,(l,th) in enumerate(zip(ports,thetas)):
            direct=(np.exp(-1j*th)*l@rho0+np.exp(1j*th)*rho0@l.conj().T)/math.sqrt(2)
            check(label+'_Mvec_'+str(j),old.residual(old.unvec(maps[j]@old.vec(rho0),d)-direct),1e-12)
        def rhs(t,y):
            v=y.reshape(blocks,d2);dv=v@gen.T
            fs=[float(f(t)) for f in filters]
            for j in range(n):dv[1+j]+=fs[j]*(maps[j]@v[0])
            for z,(j,k) in enumerate(pairs):
                dv[1+n+z]+=fs[j]*(maps[j]@v[1+k])+fs[k]*(maps[k]@v[1+j])
                if shot and j==k:dv[1+n+z]+=.5*fs[j]*fs[k]*v[0]
            return dv.reshape(-1)
        sol=solve_ivp(rhs,(0.,1.),y0.reshape(-1),method='DOP853',rtol=1e-10,atol=1e-12,t_eval=[1.])
        if not sol.success or not np.isfinite(sol.y).all():raise ValueError('ODE failed: '+sol.message)
        v=sol.y[:,-1].reshape(blocks,d2);rho=old.unvec(v[0],d)
        means=np.array([np.trace(old.unvec(v[1+j],d)) for j in range(n)])
        second=np.zeros((n,n),complex)
        for z,(j,k) in enumerate(pairs):second[j,k]=second[k,j]=np.trace(old.unvec(v[1+n+z],d))
        check(label+'_rho_trace',abs(np.trace(rho)-1),1e-9)
        check(label+'_rho_hermitian',old.residual(rho-rho.conj().T),1e-9)
        check(label+'_rho_positive',max(0.,-float(np.linalg.eigvalsh((rho+rho.conj().T)/2).min())),1e-9)
        check(label+'_imaginary',max(float(np.max(np.abs(means.imag))),float(np.max(np.abs(second.imag)))),1e-9)
        cov=second.real-np.outer(means.real,means.real)
        check(label+'_classical_covariance_positive',max(0.,-float(np.linalg.eigvalsh(cov).min())),1e-9)
        return {'means':means.real.tolist(),'second':second.real.tolist(),'covariance':cov.tolist(),'nfev':sol.nfev},rho

A construção de Davies (1974, sistematizada em Davies-Spohn-Lebowitz)
gera o dissipador GKSL como limite de acoplamento fraco com banho térmico
e tempo coarse-grained $\tau \gg 1/\omega_{\min}$.  Para um sistema com
Hamiltoniano $H_S$ acoplado a um banho via $V = \sum_{\alpha} A_{\alpha}
\otimes B_{\alpha}$, o dissipador resultante tem a forma
\begin{equation}
\mathcal{D}[\rho] \;=\;
\sum_{\omega, \alpha\beta}
\gamma_{\alpha\beta}(\omega) \left[
A_{\beta}(\omega) \rho A_{\alpha}^{\dagger}(\omega)
- \tfrac{1}{2} \{ A_{\alpha}^{\dagger}(\omega) A_{\beta}(\omega), \rho \}
\right],
\label{eq:dissipator-davies}
\end{equation}
onde $A_{\alpha}(\omega)$ são as componentes de Fourier de $A_{\alpha}$ sob
o fluxo de $H_S$, e $\gamma_{\alpha\beta}(\omega)$ é a transformada de
Fourier da função de correlação do banho.  A condição KMS no banho
\begin{equation}
\gamma_{\alpha\beta}(-\omega) \;=\; e^{-\beta_{\text{KMS}}\omega}\,
\gamma_{\beta\alpha}(\omega)
\label{eq:KMS-condition}
\end{equation}
garante que o dissipador preserva o estado de Gibbs como ponto fixo.  Esta
é a estrutura geral.  A \TGL{} corresponde ao caso onde $H_S = \Kpartial$
(gerador modular substituindo o Hamiltoniano usual) e
$\beta_{\text{KMS}} = 1$ (temperatura modular), com
$\gamma(\omega) \propto \betatgl$ uniformemente em $\omega$.

\subsection{A forma compacta $L = \sqrt{\betatgl}\,\sqrt{\Kpartial}$}
\label{sec:Lcompact}

Sob a condição~\eqref{eq:KMS-condition} com $\beta_{\text{KMS}} = 1$ e
acoplamento uniforme $\betatgl$, o dissipador~\eqref{eq:dissipator-davies}
admite a forma canônica
\begin{equation}
\mathcal{D}[\rho] \;=\;
L \rho L^{\dagger}
- \tfrac{1}{2}\{ L^{\dagger} L, \rho \},
\qquad
L \;=\; \sqrt{\betatgl} \, \sqrt{\Kpartial}.
\label{eq:L-compact-form}
\end{equation}
Esta forma compacta é o coração algébrico da \TGL{}: o gerador completo da
dinâmica é o produto de duas raízes quadradas.  A primeira ($\sqrt{\betatgl}$)
é \emph{escalar} e dimensionalmente neutra; a segunda ($\sqrt{\Kpartial}$)
é \emph{operacional} e carrega a estrutura modular.  A operação radical
$g = \sqrt{|\Lphi|}$ apresentada na Seção~\ref{sec:radicalization} é
exatamente o conteúdo dimensional de $L$.

